WITH filtered AS (SELECT id, supplier_name, country, rating, CONCAT_WS('-', supplier_name, city) AS supplier_name_city_key FROM suppliers WHERE rating < 1.8) SELECT *, DENSE_RANK() OVER (ORDER BY rating NULLS LAST) AS rating_dense_rank, LAST_VALUE(rating, TRUE) OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_rating, RANK() OVER (ORDER BY rating NULLS FIRST) AS rating_rank FROM filtered WHERE country = 'SG';
